-- Enchant suggestions: the best permanent enchant for each equipped item.
--
-- EverGear.Enchants (Data/Enchants.lua, generated by evergear-backend's
-- enchants_to_lua.py) lists every confirmed permanent enchant in WoW Forever,
-- keyed by the spell that applies it: Enchanting formulas (kind "enchanting")
-- and item enhancements such as armor kits and scopes (kind "item").
--
-- An enchant is suggested for an item when:
--   * it goes on that slot, and on that kind of weapon (enchant.weapon:
--     melee / twoHand / shield / bowGun / offhand; enchant.weaponTypes narrows
--     further, e.g. the counterweight isn't for staves);
--   * the item's level is at least enchant.minItemLevel (armor kits, scopes);
--   * the character can use it: class (Zul'Gurub enchants), character level
--     (enchant.reqLevel, against the look-ahead level like item upgrades);
--   * it can be had, following the same filters as item upgrades:
--       - Enchanting formulas: Enchanting ticked in the profession filter and
--         the Craft source type on. Anyone can have an enchanter put one on,
--         so BoE Only doesn't hide them, and the formula's skill isn't a
--         limit -- it's shown so the player knows what to ask for.
--       - Crafted items (armor kits, scopes): their profession ticked and
--         Craft on. Blacksmithing attachments need Blacksmithing to use, so
--         BoE Only on Blacksmithing hides them (like a BoP item).
--       - Quest / vendor / drop items: that source type's checkbox on.
-- Enchants score with the active EP profile like items do: stats, armor, and
-- weaponDamage turned into DPS with the weapon's speed. Flat health and mana
-- (arcanums) count as Stamina (10 health each) and Intellect (15 mana each).
-- Proc enchants (Crusader, Fiery Weapon, ...) have no plain stat value yet and
-- score 0, so they're never "best".

EverGear = EverGear or {}

local HEALTH_PER_STAMINA = 10
local MANA_PER_INTELLECT = 15

-- enchantId (the number in an item link) -> list of enchants giving it.
local byEnchantId

local function EnchantsByEnchantId()
    if byEnchantId then return byEnchantId end
    byEnchantId = {}
    for _, enchant in pairs(EverGear.Enchants or {}) do
        if enchant.enchantId then
            byEnchantId[enchant.enchantId] = byEnchantId[enchant.enchantId] or {}
            table.insert(byEnchantId[enchant.enchantId], enchant)
        end
    end
    return byEnchantId
end

-- The enchant id in an item link ("item:id:enchant:..."), or nil if none.
function EverGear:GetEnchantIdFromLink(itemLink)
    local enchantId = type(itemLink) == "string" and tonumber(itemLink:match("item:%-?%d+:(%-?%d+)"))
    if enchantId and enchantId > 0 then return enchantId end
    return nil
end

-- One known enchant for an enchant id (the first; they all give the same
-- effect), or nil.
function EverGear:GetEnchantByEnchantId(enchantId)
    local list = enchantId and EnchantsByEnchantId()[enchantId]
    return list and list[1] or nil
end

function EverGear:GetEnchant(spellId)
    return spellId and self.Enchants and self.Enchants[spellId] or nil
end

-- ===== What an item is, as far as enchants care =====

local RANGED_SUBTYPES = { Bows = "bow", Guns = "gun", Crossbows = "crossbow", Thrown = "thrown", Wands = "wand" }

-- { itemLevel, weaponType, isTwoHand, isWeapon, speed } for an item id or link,
-- from the addon's data when it has the item, the client's otherwise.
function EverGear:GetEnchantTargetInfo(itemIdOrLink)
    local itemId = type(itemIdOrLink) == "number" and itemIdOrLink or self:GetItemIDFromLink(itemIdOrLink)
    if not itemId then return nil end
    local link = type(itemIdOrLink) == "string" and itemIdOrLink or ("item:" .. itemId)
    local info = {}
    local item = self:GetItem(itemId)
    if item then
        info.itemLevel = item.ilvl
        info.weaponType = item.weaponType
        info.isTwoHand = item.isTwoHand == true
        info.speed = item.stats and item.stats.WEAPON_SPEED
    end
    -- This client has C_Item.GetItemInfo, not the bare global (see UI.lua).
    local getItemInfo = (C_Item and C_Item.GetItemInfo) or GetItemInfo
    local itemLevel, subType, equipLoc
    if getItemInfo then
        local _
        _, _, _, itemLevel, _, _, subType, _, equipLoc = getItemInfo(link)
    end
    info.itemLevel = info.itemLevel or itemLevel
    if equipLoc and equipLoc ~= "" then
        if equipLoc == "INVTYPE_2HWEAPON" then info.isTwoHand = true end
        if not info.weaponType then
            if equipLoc == "INVTYPE_SHIELD" then
                info.weaponType = "shield"
            elseif equipLoc == "INVTYPE_HOLDABLE" then
                info.weaponType = "offhand"
            elseif RANGED_SUBTYPES[subType] then
                info.weaponType = RANGED_SUBTYPES[subType]
            elseif equipLoc:find("WEAPON") then
                info.weaponType = "melee"
            end
        end
    end
    if info.weaponType and not info.speed and self.ReadLiveItemStats then
        local stats = self:ReadLiveItemStats(link)
        info.speed = stats and stats.WEAPON_SPEED
    end
    return info
end

local MELEE_TYPES = {
    axe = true, mace = true, sword = true, dagger = true, ["fist weapon"] = true,
    polearm = true, staff = true, melee = true,
}
local BOW_GUN = { bow = true, gun = true, crossbow = true }

local function FitsWeapon(enchant, target)
    local kind = enchant.weapon
    if not kind then return true end
    local weaponType = target.weaponType
    if kind == "melee" then
        if not MELEE_TYPES[weaponType] then return false end
    elseif kind == "twoHand" then
        if not (MELEE_TYPES[weaponType] and target.isTwoHand) then return false end
    elseif kind == "shield" then
        if weaponType ~= "shield" then return false end
    elseif kind == "bowGun" then
        if not BOW_GUN[weaponType] then return false end
    elseif kind == "offhand" then
        if weaponType ~= "offhand" then return false end
    end
    if enchant.weaponTypes then
        for _, t in ipairs(enchant.weaponTypes) do
            if t == weaponType then return true end
        end
        return false
    end
    return true
end

local function GoesInSlot(enchant, slotToken)
    for _, s in ipairs(enchant.slots or {}) do
        if s == slotToken then return true end
    end
    return false
end

-- Can this enchant go on this item in this slot (slot, weapon kind, item level)?
function EverGear:CanEnchantGoOn(enchant, slotToken, target)
    if not (enchant and target and GoesInSlot(enchant, slotToken)) then return false end
    if not FitsWeapon(enchant, target) then return false end
    if (enchant.minItemLevel or 0) > 0 and (target.itemLevel or 0) < enchant.minItemLevel then return false end
    return true
end

-- ===== Can the player get it =====

local SOURCE_FILTER_KEYS = {
    crafted = { "craft" }, quest = { "quest" }, vendor = { "vendor" },
    drop = { "worldDrop", "dungeonDrop" }, trainer = { "craft" },
}

function EverGear:CanGetEnchant(enchant, charDB, playerInfo, effectiveLevel)
    if enchant.classes then
        local ok = false
        for _, c in ipairs(enchant.classes) do
            if c == playerInfo.classToken then ok = true end
        end
        if not ok then return false end
    end
    if enchant.reqLevel and enchant.reqLevel > effectiveLevel then return false end
    local sourceFilters = charDB.filters or {}
    local professionFilter = charDB.professionFilter or {}
    if enchant.kind == "enchanting" then
        return professionFilter.Enchanting ~= false and sourceFilters.craft ~= false
    end
    if enchant.profession then
        if professionFilter[enchant.profession] == false then return false end
        if enchant.useProfession and (charDB.professionBoEOnly or {})[enchant.useProfession] then return false end
    end
    -- An item: at least one of its sources must be switched on.
    local sources = enchant.source or {}
    if #sources == 0 then return true end
    for _, source in ipairs(sources) do
        for _, key in ipairs(SOURCE_FILTER_KEYS[source] or {}) do
            if sourceFilters[key] ~= false then return true end
        end
    end
    return false
end

-- ===== Scoring =====

function EverGear:ScoreEnchant(enchant, slotToken, target)
    if not enchant or enchant.proc then return 0 end
    local stats = {}
    for k, v in pairs(enchant.stats or {}) do stats[k] = v end
    if stats.HEALTH then
        stats.STAMINA = (stats.STAMINA or 0) + stats.HEALTH / HEALTH_PER_STAMINA
        stats.HEALTH = nil
    end
    if stats.MANA then
        stats.INTELLECT = (stats.INTELLECT or 0) + stats.MANA / MANA_PER_INTELLECT
        stats.MANA = nil
    end
    local dps = 0
    if (enchant.weaponDamage or 0) > 0 and target and (target.speed or 0) > 0 then
        dps = enchant.weaponDamage / target.speed
    end
    return self:ScoreStats(stats, enchant.armor or 0, dps, slotToken == "RangedSlot")
end

-- ===== Player's own Enchanting skill (for "you can make this") =====

function EverGear:GetProfessionSkill(professionName)
    if not (GetNumSkillLines and GetSkillLineInfo) then return nil end
    for i = 1, GetNumSkillLines() do
        local name, isHeader, _, rank = GetSkillLineInfo(i)
        if not isHeader and name == professionName then return rank end
    end
    return nil
end

-- ===== Suggestions =====

-- Every enchant that can go on this item in this slot, scored, best first:
-- { { enchant, score }, ... }. options.ignoreAvailability lists them all
-- regardless of filters / level (for picking one in a gear set).
function EverGear:GetEnchantsForItem(slotToken, itemIdOrLink, options)
    local target = self:GetEnchantTargetInfo(itemIdOrLink)
    if not target then return {}, nil end
    local charDB = self:GetCharDB()
    local playerInfo = self:GetPlayerInfo()
    local effectiveLevel = math.max(playerInfo.level or 1, charDB.lookaheadLevel or playerInfo.level or 1)
    local list = {}
    for _, enchant in pairs(self.Enchants or {}) do
        if self:CanEnchantGoOn(enchant, slotToken, target)
            and ((options and options.ignoreAvailability) or self:CanGetEnchant(enchant, charDB, playerInfo, effectiveLevel))
        then
            table.insert(list, { enchant = enchant, score = self:ScoreEnchant(enchant, slotToken, target) })
        end
    end
    table.sort(list, function(a, b)
        if a.score ~= b.score then return a.score > b.score end
        return a.enchant.spellId < b.enchant.spellId
    end)
    return list, target
end

-- The enchant suggestion for what's equipped in a slot:
-- { best = { enchant, score } or nil, current = <enchant or nil>,
--   currentScore = <number>, hasBest = <bool>, others = { ... } }
-- best is only set when it beats the item's current enchant. nil when the
-- slot is empty or nothing can go on the item.
function EverGear:GetEnchantSuggestion(slotToken, itemLink)
    if not itemLink then return nil end
    local list, target = self:GetEnchantsForItem(slotToken, itemLink)
    if #list == 0 then return nil end
    local currentId = self:GetEnchantIdFromLink(itemLink)
    local current = currentId and self:GetEnchantByEnchantId(currentId)
    local currentScore = current and self:ScoreEnchant(current, slotToken, target) or 0
    local result = { current = current, currentEnchantId = currentId, currentScore = currentScore, others = {} }
    for _, entry in ipairs(list) do
        if entry.score > 0 and entry.score > currentScore then
            if not result.best then
                result.best = entry
            elseif #result.others < 3 then
                table.insert(result.others, entry)
            end
        end
    end
    if not result.best then
        if current and currentScore > 0 then
            result.hasBest = true
        else
            return nil  -- nothing that adds anything for this profile
        end
    end
    return result
end

-- Short "where it comes from" for an enchant, e.g. "Enchanting (140)" or
-- "Leatherworking, quest".
local SOURCE_LABELS = { trainer = "trainer", vendor = "vendor", drop = "drop", quest = "quest", crafted = "crafted" }

function EverGear:GetEnchantSourceSummary(enchant)
    if enchant.kind == "enchanting" then
        local text = "Enchanting (" .. (enchant.skill or "?") .. ")"
        local own = self:GetProfessionSkill("Enchanting")
        if own and enchant.skill and own >= enchant.skill then
            text = text .. ", you can make it"
        end
        return text
    end
    local parts = {}
    if enchant.profession then
        table.insert(parts, enchant.profession .. (enchant.skill and (" (" .. enchant.skill .. ")") or ""))
    end
    for _, source in ipairs(enchant.source or {}) do
        if source ~= "crafted" or not enchant.profession then
            table.insert(parts, SOURCE_LABELS[source] or source)
        end
    end
    return #parts > 0 and table.concat(parts, ", ") or "Unknown source"
end

-- The name to show: formulas without their "Enchant " prefix.
function EverGear:GetEnchantDisplayName(enchant)
    if not (enchant and enchant.name) then return "Unknown enchant" end
    return (enchant.name:gsub("^Enchant ", ""))
end

-- Icon: the item's for item enhancements, a generic enchanting one for
-- formulas (the spells' own icons are all the same scroll).
function EverGear:GetEnchantIcon(enchant)
    if enchant and enchant.itemId then
        local getInfo = (C_Item and C_Item.GetItemInfoInstant) or GetItemInfoInstant
        local icon = getInfo and select(5, getInfo(enchant.itemId))
        if icon then return icon end
    end
    return "Interface\\Icons\\Trade_Engraving"
end
